import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side':, 'price':, 'qty':, 'seq':, 'active':True}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]
        seq_counter += 1
        seq = seq_counter

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_seq, top_id = heap[0]
                resting_price = top_price
            else:
                top_neg_price, top_seq, top_id = heap[0]
                resting_price = -top_neg_price

            # lazy deletion of stale/inactive/filled entries
            if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                heapq.heappop(heap)
                continue

            # check price compatibility
            if price is not None:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(remaining, book[top_id]['qty'])

            if side == 'buy':
                trades.append([oid, top_id, resting_price, trade_qty])
            else:
                trades.append([top_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            book[top_id]['qty'] -= trade_qty

            if book[top_id]['qty'] == 0:
                book[top_id]['active'] = False
                heapq.heappop(heap)
            # else remaining must be 0, loop will exit naturally

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq)
        # ioc and market discard remainder; filled limit orders don't need book entry

    return trades

